from typing import List

class Solution:
    def numSubarrayBoundedMax(self, nums: List[int], left: int, right: int) -> int:
        last_greater = -1
        last_at_least = -1
        answer = 0
        for i, x in enumerate(nums):
            if x > right:
                last_greater = i
            if x >= left:
                last_at_least = i
            answer += last_at_least - last_greater
        return answer

