import java.util.*;

class Solution {
    public int numSubarrayBoundedMax(int[] nums, int left, int right) {
        int lastGreater = -1, lastAtLeast = -1;
        long answer = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > right) lastGreater = i;
            if (nums[i] >= left) lastAtLeast = i;
            answer += lastAtLeast - lastGreater;
        }
        return (int) answer;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String line = sc.nextLine().trim();
        int close = line.indexOf(']');
        String numsText = line.substring(2, close);
        int[] nums;
        if (numsText.trim().isEmpty()) {
            nums = new int[0];
        } else {
            String[] parts = numsText.split(",");
            nums = new int[parts.length];
            for (int i = 0; i < parts.length; i++) nums[i] = Integer.parseInt(parts[i].trim());
        }
        String rest = line.substring(close + 1).replace("[", "").replace("]", "").replace(",", " ").trim();
        String[] bounds = rest.split("\\s+");
        int left = Integer.parseInt(bounds[0]);
        int right = Integer.parseInt(bounds[1]);
        System.out.println(new Solution().numSubarrayBoundedMax(nums, left, right));
    }
}

